import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    first_map = []
    for _ in range(N):
        first_map.append(next(iterator))

    second_map = []
    for _ in range(M):
        second_map.append(next(iterator))

    for i in range(N - M + 1):
        for j in range(N - M + 1):
            match = True
            for k in range(M):
                if first_map[i + k][k] != second_map[j + k][k]:
                    match = False
                    break
            if match:
                print(f"{i + 1} {j + 1}")
                return

if __name__ == "__main__":
    main()
